  func copyStringIntoTuple<T>(_ dest: inout T, from src: String) {
    withUnsafeMutableBytes(of: &dest) { rawDest in
      let d = rawDest.bindMemory(to: UInt8.self)

      var i = 0
      for byte in src.utf8 {
        if i >= d.count { break }
        d[i] = byte
        i += 1
      }
      if i < d.count {
